INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q24929357', '1505 Lo Mustang earthquake', 'The 1505 Lo Mustang earthquake (Nepali: सन् १५०५ को मुस्ताङ भूकम्प) occurred on 6 June 1505 and had an estimated magnitude between 8.2 and 8.8 making it one of the largest earthquakes in Nepalese history. The earthquake killed an approximate 30 percent of the Nepalese population at the time.', 1505, 6, 6, NULL, NULL, NULL, 'day', '6 June 1505', 34, 'https://en.wikipedia.org/wiki/1505_Lo_Mustang_earthquake'),
  ('Q7884900', 'unification of Nepal', 'The Unification of Nepal (Nepali: नेपालको एकीकरण, romanized: Nēpālakō ēkīkaraṇa) was the historical process of military conquest, strategic diplomacy, and state-building through which the Hill Kingdom of Gorkha unified dozens of fragmented kingdoms into the sovereign state of modern Nepal. Initiated in 1743 CE (1799 BS) by King Prithvi Narayan Shah upon his ascension to the Gorkha throne, the unification campaign spanned over seven decades, concluding after the Anglo-Nepalese War with the Treaty of Sugauli in 1816 CE (1872 BS), which established the nation''s formal international boundaries.', 1744, NULL, NULL, 1816, NULL, NULL, 'year', '1744–1816', 47, 'https://en.wikipedia.org/wiki/Unification_of_Nepal'),
  ('Q4871446', 'Battle of Kirtipur', 'The Battle of Kirtipur (Nepal bhasa : कीर्तिपुरयाउ युद्ध) occurred in 1767 during the Gorkha conquest of Nepal, and was fought at Kirtipur, one of the principal towns in the Kathmandu Valley. Kirtipur was then a walled town of 800 houses and part of the kingdom of Lalitpur.', 1767, NULL, NULL, NULL, NULL, NULL, 'year', '1767', 37, 'https://en.wikipedia.org/wiki/Battle_of_Kirtipur'),
  ('Q4871400', 'Battle of Kathmandu', 'The Battle of Kathmandu (Nepali: काठमाडौंको युद्ध) or siege of Kathmandu or siege of Kantipur occurred during the Unification of Nepal. It was fought in Kathmandu in 1768, and resulted in the defeat of its king Jaya Prakash Malla by conquerors Prithvi Narayan Shah, king of the adjoining Gorkha Kingdom.', 1768, NULL, NULL, NULL, NULL, NULL, 'year', '1768', 37, 'https://en.wikipedia.org/wiki/Battle_of_Kathmandu'),
  ('Q4870475', 'Battle of Bhaktapur', 'The Battle of Bhaktapur was the final campaign in the Gorkha conquest of Nepal. It took place in Bhaktapur in 1769, and resulted in the victory of the Gorkhali king Prithvi Narayan Shah, giving him control of the entire Kathmandu Valley and adjoining areas.', 1769, NULL, NULL, NULL, NULL, NULL, 'year', '1769', 34, 'https://en.wikipedia.org/wiki/Battle_of_Bhaktapur'),
  ('Q11138461', 'Kot Massacre', 'The Kot massacre (Nepali: कोत पर्व) took place on 14 September 1846 when then Kaji Jung Bahadur Kunwar and his brothers killed about 30-40 civil officials, military officers and palace guards of the Nepalese palace court including the Prime Minister of Nepal and a relative of the King, Chautariya Fateh Jung Shah along with other senior-most ministers and army generals at the palace armory (Kot) of Hanuman Dhoka in Kathmandu. The Kot meeting was called upon by Queen Rajya Laxmi Devi after the same night murder of her confidante Kaji Gagan Singh Bhandari while performing worship at his prayer…', 1846, 9, 14, NULL, NULL, NULL, 'day', '14 September 1846', 41, 'https://en.wikipedia.org/wiki/Kot_massacre'),
  ('Q65396627', '1885 Nepal coup d''état', 'The 1885 Nepal coup d''état (Nepali: ४२ सालको पर्व) was a coup d''état led by Khadga Shumsher, Bhim Shumsher, Bir Shumsher, and Dambar Shumsher on 22 November 1885.', 1885, 11, 22, NULL, NULL, NULL, 'day', '22 November 1885', 30, 'https://en.wikipedia.org/wiki/1885_Nepal_coup_d''%C3%A9tat'),
  ('Q3492593', '1934 Bihar earthquake', 'The 1934 Nepal–India earthquake or 1934 Bihar–Nepal earthquake was one of the worst earthquakes in India''s history. The towns of Munger and Muzaffarpur were completely destroyed.', 1934, 1, 15, NULL, NULL, NULL, 'day', '15 January 1934', 58, 'https://en.wikipedia.org/wiki/1934_Nepal%E2%80%93India_earthquake'),
  ('Q383614', 'Battle of Kohima', 'The Battle of Kohima was the turning point of the Japanese U-Go offensive into British India in 1944 during the Second World War. It took place in three stages from 4 April to 22 June 1944 around the town of Kohima, now the capital city of the state of Nagaland in Northeast India.', 1944, NULL, NULL, 1944, 6, 22, 'year', '1944', 66, 'https://en.wikipedia.org/wiki/Battle_of_Kohima'),
  ('Q19605695', 'Revolution of 1951, Nepal', 'The 1950–1951 Nepalese revolution, also known as Saat Saalko Kranti (Nepali: सात सालको क्रान्ति, romanized: Sāt Sālko Krānti, lit. ''The Seven Year Revolution'') was a revolution in the Kingdom of Nepal that brought an end to Rana rule of Nepal which had lasted for 104 years.', 1951, NULL, NULL, NULL, NULL, NULL, 'year', '1951', 34, 'https://en.wikipedia.org/wiki/1950%E2%80%931951_Nepalese_revolution'),
  ('Q107535325', '1960 Nepal coup d''état', '1960 Nepal coup d''état was a coup d''état led by King Mahendra on 15 December 1960. The same day, he dismissed the cabinet of B.P. Koirala and imprisoned Koirala.', 1960, 12, 15, NULL, NULL, NULL, 'day', '15 December 1960', 34, 'https://en.wikipedia.org/wiki/1960_Nepal_coup_d''%C3%A9tat'),
  ('Q1783955', '1990 People''s Movement', 'The 1990 People''s Movement (Nepali: २०४६ जनआन्दोलन, romanized: 2046 Jana Andolan) was a multiparty movement in Nepal that brought an end to absolute monarchy and the beginning of constitutional monarchy. It also eliminated the Panchayat system.', 1990, 4, 8, 1990, 4, 8, 'day', '8 April 1990', 57, 'https://en.wikipedia.org/wiki/1990_Nepalese_revolution'),
  ('Q1064550', 'PIA Flight 268', 'Pakistan International Airlines Flight 268 was an Airbus A300, registration AP-BCP, which crashed while approaching Kathmandu''s Tribhuvan International Airport on 28 September 1992. All 167 people on board were killed.', 1992, 9, 28, NULL, NULL, NULL, 'day', '28 September 1992', 53, 'https://en.wikipedia.org/wiki/Pakistan_International_Airlines_Flight_268'),
  ('Q4919790', 'Thai Airways International Flight 311', 'Thai Airways International Flight 311 (TG311/THA311) was a scheduled flight from Bangkok, Thailand''s Don Mueang International Airport to Kathmandu, Nepal''s Tribhuvan International Airport. On 31 July 1992, at 07:00:26 UTC (12:45:26 NST; 14:00:26 ICT), the Airbus A310 operating the route crashed into the side of a mountain 37 kilometres (23 mi; 20 nmi) north of Kathmandu, killing all 113 passengers and crew members on board.', 1992, 7, 31, NULL, NULL, NULL, 'day', '31 July 1992', 58, 'https://en.wikipedia.org/wiki/Thai_Airways_International_Flight_311'),
  ('Q2002975', 'Nepalese Civil War', 'The Nepalese Civil War (1996–2006) was a protracted and countrywide armed conflict in the then Kingdom of Nepal between the Kingdom''s rulers and the Communist Party of Nepal (Maoist), with the latter making significant use of guerrilla warfare. It began on 13 February 1996, when the CPN(M) initiated an insurgency with the stated purpose of overthrowing the Nepali monarchy and establishing a people''s republic.', 1996, 2, 13, 2006, 11, 21, 'day', '13 February 1996 – 21 November 2006', 70, 'https://en.wikipedia.org/wiki/Nepalese_Civil_War'),
  ('Q487163', 'Nepalese royal massacre', 'The Nepalese royal massacre (also called Durbar Hatyakanda, दरबार हत्याकाण्ड) was a mass shooting which occurred on 1 June 2001 (19 Jestha 2058 Nepal B.S.) at the Narayanhiti Palace, the then-residence of the Nepali monarchy, resulting in the deaths of nine members of the royal family, including King Birendra and Queen Aishwarya. A government-appointed inquiry team named Crown Prince Dipendra as the perpetrator of the massacre.', 2001, 6, 1, NULL, NULL, NULL, 'day', '1 June 2001', 70, 'https://en.wikipedia.org/wiki/Nepalese_royal_massacre'),
  ('Q19659502', '2005 Nepal coup d''état', 'A coup d''état in Nepal began on 1 February, when democratically elected members of the country''s ruling party, the Nepali Congress, were deposed by Gyanendra, King of Nepal. The parliament was reinstated in 2006, when the king agreed to give up absolute power following the 2006 revolution.', 2005, 2, 1, NULL, NULL, NULL, 'day', '1 February 2005', 37, 'https://en.wikipedia.org/wiki/2005_Nepal_coup_d''%C3%A9tat'),
  ('Q1860910', 'Yeti Airlines Flight 101', 'Yeti Airlines Flight 101 was a domestic flight in Nepal that crashed on final approach to Tenzing-Hillary Airport in the town of Lukla in eastern Nepal on 8 October 2008. The De Havilland Canada DHC-6 Twin Otter Series 200 registered as 9N-AFE originated from Tribhuvan International Airport in Kathmandu.', 2008, 10, 8, NULL, NULL, NULL, 'day', '8 October 2008', 51, 'https://en.wikipedia.org/wiki/Yeti_Airlines_Flight_101'),
  ('Q571891', '2011 Sikkim earthquake', 'The 2011 Sikkim earthquake (also known as the 2011 Himalayan earthquake) occurred with a moment magnitude of 6.9 and was centered within the Kanchenjunga Conservation Area, near the border of Nepal and the Indian state of Sikkim, at 18:10 IST on Sunday, 18 September. The earthquake was felt across northeastern India, Nepal, Bhutan, Bangladesh, and southern Tibet.', 2011, 9, 18, NULL, NULL, NULL, 'day', '18 September 2011', 55, 'https://en.wikipedia.org/wiki/2011_Sikkim_earthquake'),
  ('Q2641878', 'Buddha Air Flight 103', 'On 25 September 2011, Buddha Air Flight 103, a Beechcraft 1900 commuter aircraft, crashed near Lalitpur, Nepal, while attempting to land in poor weather at nearby Kathmandu Airport. All 19 passengers and crew on board were killed.', 2011, 9, 25, NULL, NULL, NULL, 'day', '25 September 2011', 48, 'https://en.wikipedia.org/wiki/Buddha_Air_Flight_103'),
  ('Q394864', 'Agni Air Flight CHT', 'On 14 May 2012, a Dornier 228 passenger aircraft of Agni Air operating Flight CHT, crashed near Jomsom Airport, Nepal, killing 15 of the 21 people on board, including both pilots and Indian child actress Taruni Sachdev and her mother.', 2012, 5, 14, NULL, NULL, NULL, 'day', '14 May 2012', 50, 'https://en.wikipedia.org/wiki/Agni_Air_Flight_CHT'),
  ('Q3241797', 'Sita Air Flight 601', 'Sita Air Flight 601 (ST601/STA601) was a Nepalese domestic passenger flight, operated by Sita Air from Tribhuvan International Airport in Nepal''s capital Kathmandu to Tenzing-Hillary Airport in Lukla. On 28 September 2012, the Dornier 228 serving the route crashed while attempting an emergency landing at Kathmandu shortly after takeoff, killing all 19 people on board.', 2012, 9, 28, NULL, NULL, NULL, 'day', '28 September 2012', 52, 'https://en.wikipedia.org/wiki/Sita_Air_Flight_601'),
  ('Q13365876', 'Nepal Airlines Flight 555', 'Nepal Airlines Flight 555 was a short domestic scheduled flight from Pokhara Airport to Jomsom Airport in Nepal of about 20 minutes'' flying time, operated by Nepal Airlines. On 16 May 2013, the de Havilland Canada DHC-6 Twin Otter aircraft operating the flight crashed while landing at Jomsom Airport.', 2013, 5, 16, NULL, NULL, NULL, 'day', '16 May 2013', 47, 'https://en.wikipedia.org/wiki/Nepal_Airlines_Flight_555'),
  ('Q15732778', 'Nepal Airlines Flight 183', 'Nepal Airlines Flight 183 was a scheduled domestic passenger flight operated by a DHC-6 Twin Otter that on 16 February 2014 crashed into a hill near Dhikura, Nepal killing all 15 passengers and 3 crew members on board.', 2014, 2, 16, NULL, NULL, NULL, 'day', '16 February 2014', 52, 'https://en.wikipedia.org/wiki/Nepal_Airlines_Flight_183'),
  ('Q19830062', 'April 2015 Nepal earthquake', 'The April 2015 Nepal earthquake (also known as the Gorkha earthquake) killed 8,962 people and injured 21,952 across the countries of Nepal, India, China and Bangladesh. It occurred at 11:56 Nepal Standard Time on Saturday 25 April 2015, with a magnitude of Mw 7.8–7.9 or Ms 8.1 and a maximum Mercalli Intensity of X (Extreme).', 2015, 4, 25, NULL, NULL, NULL, 'day', '25 April 2015', 82, 'https://en.wikipedia.org/wiki/April_2015_Nepal_earthquake'),
  ('Q19839023', '2015 Mount Everest avalanches', 'In the afternoon of 25 April 2015, a 7.8 moment magnitude earthquake struck Nepal and surrounding countries. Tremors from the quake triggered an avalanche from Pumori into Base Camp on Mount Everest.', 2015, 4, 25, NULL, NULL, NULL, 'day', '25 April 2015', 47, 'https://en.wikipedia.org/wiki/2015_Mount_Everest_avalanches'),
  ('Q19898749', 'May 2015 Nepal earthquake', 'A major earthquake occurred in Nepal on 12 May 2015 at 12:50 pm local time (07:05 UTC) with a moment magnitude of 7.2–7.3, 18 kilometres (11 mi) southeast of Kodari. The epicenter was on the border of Dolakha and Sindhupalchowk, two districts of Nepal.', 2015, 5, 12, NULL, NULL, NULL, 'day', '12 May 2015', 53, 'https://en.wikipedia.org/wiki/May_2015_Nepal_earthquake'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q112163545', 'Tara Air Flight 197', 'Tara Air Flight 197 was a scheduled domestic flight operated by Tara Air for parent company Yeti Airlines from Pokhara Airport to Jomsom Airport in Nepal. On 29 May 2022, the De Havilland Canada DHC-6 Twin Otter aircraft carrying 22 people (19 passengers and 3 crew members) departed at 09:55 NPT (04:10 UTC) and lost contact with air traffic controllers about 12 minutes later at 10:07 (04:22).', 2022, 5, 29, NULL, NULL, NULL, 'day', '29 May 2022', 59, 'https://en.wikipedia.org/wiki/Tara_Air_Flight_197'),
  ('Q123308737', '2023 Nepal earthquake', 'A moment magnitude 5.7 earthquake struck Jajarkot, Karnali Province, Nepal, at 23:47 NPT (18:02 UTC) on 3 November 2023, killing 153 people and injuring at least 375. The earthquake was widely felt in western Nepal and northern India, and is the deadliest to strike the country since 2015.', 2023, 11, 3, NULL, NULL, NULL, 'day', '3 November 2023', 61, 'https://en.wikipedia.org/wiki/2023_Nepal_earthquake'),
  ('Q130386843', '2024 Nepal floods', 'Torrential rainfall during the annual monsoon season in early July, mid August, and late September 2024 caused massive flooding across Nepal as well as several mudslides. The September floods, which caused the most damage and deaths, were caused by the heaviest rainfall recorded in the region since at least 1970, the result of a low-pressure system.', 2024, NULL, NULL, NULL, NULL, NULL, 'year', '2024', 50, 'https://en.wikipedia.org/wiki/2024_Nepal_floods'),
  ('Q136160164', '2025 Nepalese Gen Z protests', 'In September 2025, large-scale anti-corruption protests and demonstrations took place all across Nepal, predominantly organized by Generation Z students and young citizens. Known as the "Gen Z Revolution" or "Third People''s Movement", they began parallel to a nationwide ban on numerous social media platforms including YouTube, Instagram, TikTok, X, Facebook, and WhatsApp, and were motivated by the public''s frustration with corruption and display of wealth by government officials and their families, as well as allegations of mismanagement of public funds.', 2025, 9, 8, 2025, 9, 13, 'day', '8 September 2025 – 13 September 2025', 73, 'https://en.wikipedia.org/wiki/2025_Nepalese_Gen_Z_protests'),
  ('Q141182413', '2026 Nepal–Tibet floods', 'On the morning of 26 August 2026, a series of flash floods and debris flows destroyed the Gyirong Port on the China–Nepal border and struck dozens of settlements along a 72 km (45 mi) stretch of the Trishuli River in Nepal. These events are also known as the 2026 Nepal-China floods, Bhotekoshi flood, or Rasuwa flood.', 2026, 8, 26, NULL, NULL, NULL, 'day', '26 August 2026', 77, 'https://en.wikipedia.org/wiki/2026_Nepal%E2%80%93Tibet_floods');
